// Third sibling of mm_fp32_16_pure_half_wide_bigreg_sq: same "skip
// decode for A data that's already valid __half bits" idea as _tile_
// dirty and _inline_dirty, but the dirty check is precomputed ONCE
// ahead of time (by fp32_16_compute_chunk_dirty, on the same wh this is
// called with) instead of derived on every call -- see mm_fp32_16_pure_
// half_wide_bigreg_sq_precomputed_dirty_kernel's own comment for the ncu
// evidence motivating this and why it needs a genuinely different
// (extra chunk_dirty parameter) signature rather than being a drop-in
// replacement. Launches a fully standalone kernel; none of the other
// three methods is touched by or shares code with this.
void mm_fp32_16_pure_half_wide_bigreg_sq_precomputed_dirty(TransposeType transA, TransposeType transB, double alpha,
                                                            size_t m, size_t k, size_t n, const uint16_t* wh,
                                                            size_t ld_a, const __half* B, size_t ld_b, double beta,
                                                            __half* C, size_t ld_c,
                                                            const unsigned char* chunk_dirty) {
    __half h_alpha = static_cast<__half>(static_cast<float>(alpha));
    __half h_beta = static_cast<__half>(static_cast<float>(beta));
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 8 != 0 || k % 8 != 0) {
        dim3 threads(16, 16);
        dim3 blocks(static_cast<unsigned>((n + threads.x - 1) / threads.x),
                   static_cast<unsigned>((m + threads.y - 1) / threads.y));
        mm_fp32_16_pure_half_wide_bigreg_sq_fallback_kernel<<<blocks, threads>>>(
            h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t e1 = cudaFuncSetAttribute(mm_fp32_16_pure_half_wide_bigreg_sq_precomputed_dirty_kernel<true>,
                                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                                              static_cast<int>(kGemmFp16WideBigRegSqSharedBytes));
        cudaError_t e2 = cudaFuncSetAttribute(mm_fp32_16_pure_half_wide_bigreg_sq_precomputed_dirty_kernel<false>,
                                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                                              static_cast<int>(kGemmFp16WideBigRegSqSharedBytes));
        if (e1 != cudaSuccess || e2 != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        attr_set = true;
    }

    bool skip_beta = (beta == 0.0);
    dim3 threads(kGemmFp16WideBigRegThreads);
    dim3 blocks((n + kGemmFp16WideBigRegSqBN - 1) / kGemmFp16WideBigRegSqBN,
               (m + kGemmFp16BigBM - 1) / kGemmFp16BigBM);
    if (skip_beta) {
        mm_fp32_16_pure_half_wide_bigreg_sq_precomputed_dirty_kernel<true>
            <<<blocks, threads, kGemmFp16WideBigRegSqSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C,
                                                                     ld_c, chunk_dirty);
    } else {
        mm_fp32_16_pure_half_wide_bigreg_sq_precomputed_dirty_kernel<false>
            <<<blocks, threads, kGemmFp16WideBigRegSqSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C,
                                                                     ld_c, chunk_dirty);
    }
}

// Fourth sibling of mm_fp32_16_pure_half_wide_bigreg_sq: same signature
// as the original (drop-in replacement, no extra parameter needed --
// unlike _precomputed_dirty, this needs no precomputed metadata since
// warps 4-7 simply don't check at all, and warps 0-3 derive everything
// from wh inline exactly like _inline_dirty does). See mm_fp32_16_pure_
// half_wide_bigreg_sq_warp_specialized_kernel's own comment for the full
// derivation and the (genuinely uncertain going in) motivation. Launches
// a fully standalone kernel; none of the other three methods is touched
// by or shares code with this.
void mm_fp32_16_pure_half_wide_bigreg_sq_warp_specialized(TransposeType transA, TransposeType transB, double alpha,
                                                           size_t m, size_t k, size_t n, const uint16_t* wh,
                                                           size_t ld_a, const __half* B, size_t ld_b, double beta,
                                                           __half* C, size_t ld_c) {
    __half h_alpha = static_cast<__half>(static_cast<float>(alpha));
    __half h_beta = static_cast<__half>(static_cast<float>(beta));
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 8 != 0 || k % 8 != 0) {
        dim3 threads(16, 16);
        dim3 blocks(static_cast<unsigned>((n + threads.x - 1) / threads.x),
                   static_cast<unsigned>((m + threads.y - 1) / threads.y));
        mm_fp32_16_pure_half_wide_bigreg_sq_fallback_kernel<<<blocks, threads>>>(
            h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t e1 = cudaFuncSetAttribute(mm_fp32_16_pure_half_wide_bigreg_sq_warp_specialized_kernel<true>,
                                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                                              static_cast<int>(kGemmFp16WideBigRegWarpSpecSharedBytes));
        cudaError_t e2 = cudaFuncSetAttribute(mm_fp32_16_pure_half_wide_bigreg_sq_warp_specialized_kernel<false>,
                                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                                              static_cast<int>(kGemmFp16WideBigRegWarpSpecSharedBytes));
        if (e1 != cudaSuccess || e2 != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        attr_set = true;
    }

    bool skip_beta = (beta == 0.0);
    dim3 threads(kGemmFp16WideBigRegThreads);
    dim3 blocks((n + kGemmFp16WideBigRegSqBN - 1) / kGemmFp16WideBigRegSqBN,
               (m + kGemmFp16BigBM - 1) / kGemmFp16BigBM);
    if (skip_beta) {
        mm_fp32_16_pure_half_wide_bigreg_sq_warp_specialized_kernel<true>
            <<<blocks, threads, kGemmFp16WideBigRegWarpSpecSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b,
                                                                           h_beta, C, ld_c);
    } else {
        mm_fp32_16_pure_half_wide_bigreg_sq_warp_specialized_kernel<false>
            <<<blocks, threads, kGemmFp16WideBigRegWarpSpecSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b,
                                                                           h_beta, C, ld_c);
    }
}

