// Generic CSR SpMM kernel: one thread per output element C[i,j].
// Only NO_TRANSPOSE on A is parallelised here; transA=TRANSPOSE is handled
// by the host wrapper via a column-by-column fallback.
template <typename a_t, typename b_t, typename c_t, typename index_t>
__global__ void spmm_csr_kernel(TransposeType transB, double alpha, size_t m,
                                size_t n, a_t* values, index_t* row_ptrs,
                                index_t* col_idxs, b_t* B, size_t ld_b,
                                double beta, c_t* C, size_t ld_c) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    size_t j = blockIdx.y * blockDim.y + threadIdx.y;
    if (i >= m || j >= n) return;

    double acc = 0.0;
    for (index_t p = row_ptrs[i]; p < row_ptrs[i + 1]; ++p) {
        size_t l = static_cast<size_t>(col_idxs[p]);
        double b_val = (transB == TransposeType::NO_TRANSPOSE)
                           ? static_cast<double>(B[l + j * ld_b])
                           : static_cast<double>(B[j + l * ld_b]);
        acc += static_cast<double>(values[p]) * b_val;
    }
    C[i + j * ld_c] =
        static_cast<c_t>(alpha * acc + beta * static_cast<double>(C[i + j * ld_c]));
}

template <typename a_t, typename b_t, typename c_t, typename index_t>
void mm_csr(TransposeType transA, TransposeType transB, double alpha,
            dim<2> size_A, size_t nnz, a_t* values, index_t* row_ptrs,
            index_t* col_idxs, dim<2> size_B, b_t* B, size_t ld_b,
            double beta, c_t* C, size_t ld_c, cusparseHandle_t handle) {
    size_t m = (transA == TransposeType::NO_TRANSPOSE) ? size_A[0] : size_A[1];
    size_t n = (transB == TransposeType::NO_TRANSPOSE) ? size_B[1] : size_B[0];

    if (transA == TransposeType::NO_TRANSPOSE) {
        dim3 threads(16, 16);
        dim3 blocks((m + 15) / 16, (n + 15) / 16);
        spmm_csr_kernel<<<blocks, threads>>>(transB, alpha, m, n, values,
                                             row_ptrs, col_idxs, B, ld_b,
                                             beta, C, ld_c);
        cudaDeviceSynchronize();
    }
    // transA=TRANSPOSE not yet implemented for CUDA SpMM.
}

#define INST_MM_CSR(a_t, b_t, c_t)                                           \
    template void mm_csr<a_t, b_t, c_t, int>(                                \
        TransposeType, TransposeType, double, dim<2>, size_t, a_t*, int*,    \
        int*, dim<2>, b_t*, size_t, double, c_t*, size_t,                    \
        cusparseHandle_t);                                                    \
    template void mm_csr<a_t, b_t, c_t, long>(                               \
        TransposeType, TransposeType, double, dim<2>, size_t, a_t*, long*,   \
        long*, dim<2>, b_t*, size_t, double, c_t*, size_t,                   \
        cusparseHandle_t);
FOR_ALL_FP_TRIPLES(INST_MM_CSR)
#undef INST_MM_CSR

// One thread per row of A: row i owns C's row i exclusively, so no atomics
// are needed even though several A(i, l) entries can hit the same C(i, j).
template <typename a_t, typename b_t, typename c_t, typename index_t>
__global__ void spgemm_csr_csr_kernel(double alpha, size_t m, size_t n,
                                      const index_t* __restrict__ row_ptrs_A,
                                      const index_t* __restrict__ col_idxs_A,
                                      const a_t* __restrict__ values_A,
                                      const index_t* __restrict__ row_ptrs_B,
                                      const index_t* __restrict__ col_idxs_B,
                                      const b_t* __restrict__ values_B,
                                      double beta, c_t* __restrict__ C,
                                      size_t ld_c) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= m) return;

    for (size_t j = 0; j < n; ++j)
        C[i + j * ld_c] =
            static_cast<c_t>(beta * static_cast<double>(C[i + j * ld_c]));

    for (index_t p = row_ptrs_A[i]; p < row_ptrs_A[i + 1]; ++p) {
        size_t l = static_cast<size_t>(col_idxs_A[p]);
        double scale = alpha * static_cast<double>(values_A[p]);
        for (index_t q = row_ptrs_B[l]; q < row_ptrs_B[l + 1]; ++q) {
            size_t j = static_cast<size_t>(col_idxs_B[q]);
            C[i + j * ld_c] = static_cast<c_t>(
                static_cast<double>(C[i + j * ld_c]) +
                scale * static_cast<double>(values_B[q]));
        }
    }
}

template <typename a_t, typename b_t, typename c_t, typename index_t>
void mm_csr_csr(double alpha, dim<2> size_A, index_t* row_ptrs_A,
               index_t* col_idxs_A, a_t* values_A, dim<2> size_B,
               index_t* row_ptrs_B, index_t* col_idxs_B, b_t* values_B,
               double beta, c_t* C, size_t ld_c) {
    size_t m = size_A[0];
    size_t n = size_B[1];

    size_t threads = 256;
    size_t blocks = (m + threads - 1) / threads;
    spgemm_csr_csr_kernel<<<blocks, threads>>>(
        alpha, m, n, row_ptrs_A, col_idxs_A, values_A, row_ptrs_B, col_idxs_B,
        values_B, beta, C, ld_c);
    cudaDeviceSynchronize();
}

#define INST_MM_CSR_CSR(a_t, b_t, c_t)                                      \
    template void mm_csr_csr<a_t, b_t, c_t, int>(                           \
        double, dim<2>, int*, int*, a_t*, dim<2>, int*, int*, b_t*, double, \
        c_t*, size_t);                                                      \
    template void mm_csr_csr<a_t, b_t, c_t, long>(                          \
        double, dim<2>, long*, long*, a_t*, dim<2>, long*, long*, b_t*,     \
        double, c_t*, size_t);
FOR_ALL_FP_TRIPLES(INST_MM_CSR_CSR)
#undef INST_MM_CSR_CSR


// Alias giving the existing (unqualified experimental::/cuda::) pure_half
// decode set a name symmetrical with experimental::conditional:: below --
// same entities, nothing moved or duplicated. See conditional's own header
// comment for the full explanation.
namespace experimental { namespace branchless = tomos::cuda::experimental; }

// ===========================================================================
// CONDITIONAL-DECODE DUPLICATE SET (added for A/B comparison)
//
// Every kernel/host-wrapper in this file (GEMM, mm_fp32_16_*) that decodes fp32_16 "wh" pure_half
// data now uses fp32_16_half_only_branchless_no_overflow_nomask (the
// branchless, no-overflow-guaranteed, redundant-mask-removed decode
// promoted from test-new -- see decode.md). This block duplicates the
// EXACT pre-promotion bodies of that same set of functions verbatim
// (unchanged: fp32_16_half_only / fp32_16_half_only_fast2 /
// fp32_16_half_only_branchless, all of which check `direction` and
// distinguish overflow from underflow correctly -- see those functions'
// own comments in fp32_16_pack.hpp), under the SAME names, nested inside
// a new `conditional` namespace, purely so both decode strategies can be
// benchmarked/ncu-profiled side by side without one shadowing the other.
//
// Naming: the default (unqualified experimental::X / cuda::X) names above
// this block are the "branchless" set -- see the
// `namespace branchless = tomos::cuda::experimental;` alias declared
// right after this file (GEMM, mm_fp32_16_*)'s own `experimental` namespace closes, which
// gives that existing set a symmetrical qualified name
// (tomos::cuda::experimental::branchless::X, identical entities, no code
// moved or duplicated) to pair with tomos::cuda::experimental::conditional::X
// below. Do not edit the two sets independently expecting them to diverge
// in anything but decode -- if the branchless set's non-decode logic
// changes, this block will silently go stale; it exists for a decode A/B
// comparison, not as a second copy to maintain long-term.
// ===========================================================================

namespace experimental {
namespace conditional {

__global__ void mm_fp32_16_pure_half_wide_bigreg_sq_fallback_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const __half* __restrict__ B, size_t ld_b,
    __half beta, __half* __restrict__ C, size_t ld_c) {
    size_t row = static_cast<size_t>(blockIdx.y) * blockDim.y + threadIdx.y;
    size_t col = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (row >= m || col >= n) return;
    float acc = 0.0f;
    for (size_t kk = 0; kk < k; ++kk) {
        float a = __half2float(fp32_16_half_only(wh[row + kk * ld_a]));
        float b = __half2float(B[kk + col * ld_b]);
        acc += a * b;
    }
    size_t c_idx = row + col * ld_c;
    float c_val = static_cast<float>(alpha) * acc + static_cast<float>(beta) * __half2float(C[c_idx]);
    C[c_idx] = static_cast<__half>(c_val);
}
void mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty_acongruous_fastk_precomp2_serp(
    TransposeType transA, TransposeType transB, double alpha, size_t m, size_t k, size_t n, const uint16_t* wh,
    size_t ld_a, const __half* B, size_t ld_b, double beta, __half* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 8 != 0 || k % 8 != 0 ||
        ld_c % 8 != 0 || m % kGemmFp16BigBM != 0 || n % kGemmFp16WideBigRegSqBN != 0 ||
        k % kGemmFp16WideBigRegBK != 0) {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta, C,
                                                          ld_c);
        return;
    }
    static int sm_count = -1;
    if (sm_count < 0) {
        int device = 0;
        cudaGetDevice(&device);
        cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    }
    size_t grid_blocks = ((n + kGemmFp16WideBigRegSqBN - 1) / kGemmFp16WideBigRegSqBN) *
                         ((m + kGemmFp16BigBM - 1) / kGemmFp16BigBM);
    if (grid_blocks < static_cast<size_t>(sm_count) / 2) {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta, C,
                                                          ld_c);
        return;
    }
    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t e1 = cudaFuncSetAttribute(
            mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty_acongruous_fastk_precomp2_serp_kernel<true>,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            static_cast<int>(kGemmFp16WideBigRegInlineDirtyACongruousFastkPrecomp2SerpSharedBytes));
        cudaError_t e2 = cudaFuncSetAttribute(
            mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty_acongruous_fastk_precomp2_serp_kernel<false>,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            static_cast<int>(kGemmFp16WideBigRegInlineDirtyACongruousFastkPrecomp2SerpSharedBytes));
        if (e1 != cudaSuccess || e2 != cudaSuccess) {
            cudaGetLastError();
            mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta,
                                                              C, ld_c);
            return;
        }
        attr_set = true;
    }
    bool skip_beta = (beta == 0.0);
    __half h_alpha = static_cast<__half>(static_cast<float>(alpha));
    __half h_beta = static_cast<__half>(static_cast<float>(beta));
    dim3 threads(kGemmFp16WideBigRegThreads);
    dim3 blocks((n + kGemmFp16WideBigRegSqBN - 1) / kGemmFp16WideBigRegSqBN,
               (m + kGemmFp16BigBM - 1) / kGemmFp16BigBM);
    if (skip_beta) {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty_acongruous_fastk_precomp2_serp_kernel<true>
            <<<blocks, threads, kGemmFp16WideBigRegInlineDirtyACongruousFastkPrecomp2SerpSharedBytes>>>(
                h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    } else {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty_acongruous_fastk_precomp2_serp_kernel<false>
            <<<blocks, threads, kGemmFp16WideBigRegInlineDirtyACongruousFastkPrecomp2SerpSharedBytes>>>(
                h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    }
}
__global__ void mm_fp32_16_pure_half_materialize_chunk_kernel(size_t chunk_rows, size_t row_offset, size_t k,
                                                               const uint16_t* __restrict__ wh, size_t ld_a,
                                                               __half* __restrict__ out, size_t ld_out) {
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t total = chunk_rows * k;
    if (idx >= total) return;
    size_t local_row = idx % chunk_rows;
    size_t col = idx / chunk_rows;
    size_t src_idx = (row_offset + local_row) + col * ld_a;
    size_t dst_idx = local_row + col * ld_out;
    out[dst_idx] = fp32_16_half_only(wh[src_idx]);
}
void mm_fp32_16_pure_half_gemm_materialize_fastk_precomp2_serp(TransposeType transA, TransposeType transB,
                                                                double alpha, size_t m, size_t k, size_t n,
                                                                const uint16_t* wh, size_t ld_a, const __half* B,
                                                                size_t ld_b, double beta, __half* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta, C,
                                                          ld_c);
        return;
    }

    size_t scratch_rows = std::min(kMmFp32_16PureHalfMaterializeChunkRows, m);
    __half* scratch = nullptr;
    if (cudaMalloc(&scratch, scratch_rows * k * sizeof(__half)) != cudaSuccess) {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta, C,
                                                          ld_c);
        return;
    }

    for (size_t row0 = 0; row0 < m; row0 += kMmFp32_16PureHalfMaterializeChunkRows) {
        size_t chunk_rows = std::min(kMmFp32_16PureHalfMaterializeChunkRows, m - row0);
        size_t total = chunk_rows * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_pure_half_materialize_chunk_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, ld_a, scratch,
                                                                            chunk_rows);
        gemm_fp16_mma_ptx_wide_bigreg_sq_deep4_iter_epivec_acongruous_fastk_precomp2_serp(
            TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha, chunk_rows, k, n, scratch, chunk_rows,
            const_cast<__half*>(B), ld_b, beta, C + row0, ld_c);
    }

    cudaFree(scratch);
}
void mm_fp32_16_pure_half_gemm_materialize_cached_fastk_precomp2_serp(TransposeType transA, TransposeType transB,
                                                                       double alpha, size_t m, size_t k, size_t n,
                                                                       const uint16_t* wh, size_t ld_a,
                                                                       const __half* B, size_t ld_b, double beta,
                                                                       __half* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
