                                                          ld_c);
        return;
    }

    size_t scratch_rows = std::min(kMmFp32_16PureHalfMaterializeChunkRows, m);
    size_t needed_bytes = scratch_rows * k * sizeof(__half);

    static __half* cached_scratch = nullptr;
    static size_t cached_capacity_bytes = 0;
    if (needed_bytes > cached_capacity_bytes) {
        if (cached_scratch != nullptr) {
            cudaFree(cached_scratch);
            cached_scratch = nullptr;
            cached_capacity_bytes = 0;
        }
        if (cudaMalloc(&cached_scratch, needed_bytes) != cudaSuccess) {
            cached_scratch = nullptr;
            mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta,
                                                              C, ld_c);
            return;
        }
        cached_capacity_bytes = needed_bytes;
    }

    for (size_t row0 = 0; row0 < m; row0 += kMmFp32_16PureHalfMaterializeChunkRows) {
        size_t chunk_rows = std::min(kMmFp32_16PureHalfMaterializeChunkRows, m - row0);
        size_t total = chunk_rows * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_pure_half_materialize_chunk_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, ld_a,
                                                                            cached_scratch, chunk_rows);
        gemm_fp16_mma_ptx_wide_bigreg_sq_deep4_iter_epivec_acongruous_fastk_precomp2_serp(
            TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha, chunk_rows, k, n, cached_scratch,
