        mm_fp32_16_pure_half_materialize_chunk_vec64_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, ld_a,
                                                                                  cached_scratch_vec64,
                                                                                  scratch_rows_padded);
        gemm_fp16_mma_ptx_wide_bigreg_sq_deep4_iter_epivec_acongruous_fastk_precomp2_serp(
            TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha, chunk_rows, k, n, cached_scratch_vec64,
            scratch_rows_padded, const_cast<__half*>(B), ld_b, beta, C + row0, ld_c);
    }
}
__global__ void mm_fp32_16_pure_half_materialize_chunk_dirty_kernel(size_t chunk_rows, size_t row_offset, size_t k,
                                                                      const uint16_t* __restrict__ wh, size_t ld_a,
                                                                      __half* __restrict__ out, size_t ld_out) {
    size_t row_groups = (chunk_rows + 3) / 4;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t total_groups = row_groups * k;
    if (idx >= total_groups) return;
    size_t group = idx % row_groups;
    size_t col = idx / row_groups;
    size_t local_row0 = group * 4;
    size_t src_idx0 = (row_offset + local_row0) + col * ld_a;
    size_t dst_idx0 = local_row0 + col * ld_out;
    if (local_row0 + 4 <= chunk_rows) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(&wh[src_idx0]);
        bool any_dirty = ((wh4.x | wh4.y | wh4.z | wh4.w) & 0x1u) != 0u;
        if (!any_dirty) {
            *reinterpret_cast<uint2*>(&out[dst_idx0]) = *reinterpret_cast<const uint2*>(&wh4);
        } else {
            unsigned long long h0 = __half_as_ushort(fp32_16_half_only(wh4.x));
            unsigned long long h1 = __half_as_ushort(fp32_16_half_only(wh4.y));
            unsigned long long h2 = __half_as_ushort(fp32_16_half_only(wh4.z));
            unsigned long long h3 = __half_as_ushort(fp32_16_half_only(wh4.w));
            unsigned long long packed = h0 | (h1 << 16) | (h2 << 32) | (h3 << 48);
            *reinterpret_cast<unsigned long long*>(&out[dst_idx0]) = packed;
        }
    } else {
        for (size_t r = local_row0; r < chunk_rows; ++r) {
            size_t src_idx = (row_offset + r) + col * ld_a;
            size_t dst_idx = r + col * ld_out;
            out[dst_idx] = fp32_16_half_only(wh[src_idx]);
        }
    }
}
void mm_fp32_16_pure_half_gemm_materialize_cached_dirty_fastk_precomp2_serp(TransposeType transA,
                                                                              TransposeType transB, double alpha,
                                                                              size_t m, size_t k, size_t n,
                                                                              const uint16_t* wh, size_t ld_a,
                                                                              const __half* B, size_t ld_b,
                                                                              double beta, __half* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_pure_half_wide_bigreg_sq_inline_dirty(transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta, C,
                                                          ld_c);
        return;
    }
    if (ld_a % 4 != 0) {
        mm_fp32_16_pure_half_gemm_materialize_cached_vec64_fastk_precomp2_serp(transA, transB, alpha, m, k, n, wh,
                                                                                 ld_a, B, ld_b, beta, C, ld_c);
        return;
    }

    size_t scratch_rows = std::min(kMmFp32_16PureHalfMaterializeChunkRows, m);
    size_t scratch_rows_padded = (scratch_rows + 3) / 4 * 4;
    size_t needed_bytes = scratch_rows_padded * k * sizeof(__half);

    static __half* cached_scratch_dirty = nullptr;
    static size_t cached_capacity_bytes_dirty = 0;
    if (needed_bytes > cached_capacity_bytes_dirty) {
        if (cached_scratch_dirty != nullptr) {
            cudaFree(cached_scratch_dirty);
            cached_scratch_dirty = nullptr;
            cached_capacity_bytes_dirty = 0;
        }
        if (cudaMalloc(&cached_scratch_dirty, needed_bytes) != cudaSuccess) {
            cached_scratch_dirty = nullptr;
            mm_fp32_16_pure_half_gemm_materialize_cached_fastk_precomp2_serp(transA, transB, alpha, m, k, n, wh,
                                                                              ld_a, B, ld_b, beta, C, ld_c);
            return;
        }
        cached_capacity_bytes_dirty = needed_bytes;
    }

    for (size_t row0 = 0; row0 < m; row0 += kMmFp32_16PureHalfMaterializeChunkRows) {
        size_t chunk_rows = std::min(kMmFp32_16PureHalfMaterializeChunkRows, m - row0);
        size_t row_groups = (chunk_rows + 3) / 4;
        size_t total = row_groups * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_pure_half_materialize_chunk_dirty_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, ld_a,
                                                                                  cached_scratch_dirty,
                                                                                  scratch_rows_padded);
        gemm_fp16_mma_ptx_wide_bigreg_sq_deep4_iter_epivec_acongruous_fastk_precomp2_serp(
            TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha, chunk_rows, k, n, cached_scratch_dirty,
            scratch_rows_padded, const_cast<__half*>(B), ld_b, beta, C + row0, ld_c);
    }
}
