void mm_fp32_16_pure_half_wide_bigreg_sq_tile_dirty(TransposeType transA, TransposeType transB, double alpha,
                                                     size_t m, size_t k, size_t n, const uint16_t* wh, size_t ld_a,
                                                     const __half* B, size_t ld_b, double beta, __half* C,
                                                     size_t ld_c) {
    __half h_alpha = static_cast<__half>(static_cast<float>(alpha));
    __half h_beta = static_cast<__half>(static_cast<float>(beta));
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 8 != 0 || k % 8 != 0) {
        dim3 threads(16, 16);
        dim3 blocks(static_cast<unsigned>((n + threads.x - 1) / threads.x),
                   static_cast<unsigned>((m + threads.y - 1) / threads.y));
        mm_fp32_16_pure_half_wide_bigreg_sq_fallback_kernel<<<blocks, threads>>>(
            h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t e1 = cudaFuncSetAttribute(mm_fp32_16_pure_half_wide_bigreg_sq_kernel<true, true>,
                                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                                              static_cast<int>(kGemmFp16WideBigRegSqSharedBytes));
        cudaError_t e2 = cudaFuncSetAttribute(mm_fp32_16_pure_half_wide_bigreg_sq_kernel<false, true>,
                                              cudaFuncAttributeMaxDynamicSharedMemorySize,
                                              static_cast<int>(kGemmFp16WideBigRegSqSharedBytes));
        if (e1 != cudaSuccess || e2 != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        attr_set = true;
    }

    bool skip_beta = (beta == 0.0);
    dim3 threads(kGemmFp16WideBigRegThreads);
    dim3 blocks((n + kGemmFp16WideBigRegSqBN - 1) / kGemmFp16WideBigRegSqBN,
               (m + kGemmFp16BigBM - 1) / kGemmFp16BigBM);
    const size_t num_tiles = (k + kGemmFp16WideBigRegBK - 1) / kGemmFp16WideBigRegBK;
    size_t tile_dirty_bytes = static_cast<size_t>(blocks.y) * num_tiles;

    static unsigned char* d_tile_dirty = nullptr;
    static size_t d_tile_dirty_capacity = 0;
    if (tile_dirty_bytes > d_tile_dirty_capacity) {
        if (d_tile_dirty) cudaFree(d_tile_dirty);
        d_tile_dirty = nullptr;
        d_tile_dirty_capacity = 0;
        if (cudaMalloc(&d_tile_dirty, tile_dirty_bytes) == cudaSuccess) {
            d_tile_dirty_capacity = tile_dirty_bytes;
        }
    }
    if (!d_tile_dirty) {
        // Allocation failed -- fall back to the always-correct, always-
        // decode kernel rather than dereferencing a null tile_dirty.
        if (skip_beta) {
            mm_fp32_16_pure_half_wide_bigreg_sq_kernel<true, false>
                <<<blocks, threads, kGemmFp16WideBigRegSqSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b,
                                                                         h_beta, C, ld_c, nullptr);
        } else {
            mm_fp32_16_pure_half_wide_bigreg_sq_kernel<false, false>
                <<<blocks, threads, kGemmFp16WideBigRegSqSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b,
                                                                         h_beta, C, ld_c, nullptr);
        }
        return;
    }

    dim3 check_blocks(static_cast<unsigned>(num_tiles), blocks.y);
    fp32_16_compute_tile_dirty_kernel<<<check_blocks, 256>>>(wh, m, k, ld_a, kGemmFp16BigBM, kGemmFp16WideBigRegBK,
                                                              num_tiles, d_tile_dirty);

    if (skip_beta) {
        mm_fp32_16_pure_half_wide_bigreg_sq_kernel<true, true>
            <<<blocks, threads, kGemmFp16WideBigRegSqSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C,
                                                                     ld_c, d_tile_dirty);
    } else {
        mm_fp32_16_pure_half_wide_bigreg_sq_kernel<false, true>
            <<<blocks, threads, kGemmFp16WideBigRegSqSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C,
                                                                     ld_c, d_tile_dirty);
    }
}
